def get_directories(self, directory: (PathLike | None)=None, packages: (
    list[str | tuple[str, str]] | None)=None) ->list[PathLike]:
        """
        Given `directory` and `packages` arguments, return a list of all the
        directories that should be used for serving static files from.
        """
        directories = []
        if directory is not None:
            directories.append(directory)

        for package in packages or []:
            if isinstance(package, tuple):
                package, statics_dir = package
            else:
                statics_dir = "statics"
            spec = importlib.util.find_spec(package)
            assert spec is not None, f"Package {package!r} could not be found."
            assert spec.origin is not None, f"Package {package!r} could not be found."
            package_directory = os.path.normpath(os.path.join(spec.origin, "..", statics_dir))
            assert os.path.isdir(
                package_directory
            ), f"Directory '{statics_dir!r}' in package {package!r} could not be found."
            directories.append(package_directory)

        return directories

def lookup_path(self, path: str) ->tuple[str, os.stat_result | None]:
    for directory in self.all_directories:
        joined_path = os.path.join(directory, path)
        if self.follow_symlink:
            full_path = os.path.abspath(joined_path)
        else:
            full_path = os.path.realpath(joined_path)

        # Ensure we don't allow path traversal by checking that the full path
        # is within the directory bounds
        if self.follow_symlink:
            # When following symlinks, we need to resolve the real path of the directory
            # to properly check the path traversal
            try:
                real_directory = os.path.realpath(directory)
                if os.path.commonpath([full_path, real_directory]) != real_directory:
                    continue
            except Exception:
                continue
        else:
            # When not following symlinks, use the standard approach
            try:
                real_directory = os.path.realpath(directory)
                if os.path.commonpath([full_path, real_directory]) != real_directory:
                    continue
            except Exception:
                continue

        try:
            stat_result = os.stat(full_path)
            return full_path, stat_result
        except (FileNotFoundError, NotADirectoryError):
            continue
    return "", None

def file_response(self, full_path: PathLike, stat_result: os.stat_result,
